#requires -Version 5.1
[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$ReleasePath,[Parameter(Mandatory=$true)][int]$Port,[Parameter(Mandatory=$true)][string]$CanonicalOrigin)
$ErrorActionPreference='Stop';function Need([bool]$ok,[string]$m){if(-not $ok){throw "VALIDATION_FAILED: $m"}}
$python=Join-Path $ReleasePath 'runtime\python.exe';Need (Test-Path $python) 'candidate runtime absent';$c=@(Get-NetTCPConnection -LocalAddress 127.0.0.1 -LocalPort $Port -State Listen);Need ($c.Count -eq 1) 'listener is not singular';$p=Get-CimInstance Win32_Process -Filter "ProcessId=$($c[0].OwningProcess)";Need ($p.CommandLine -like "*$python*") 'listener is not candidate packaged runtime';foreach($path in '/','/api/health','/api/health/ping'){Need ((Invoke-WebRequest -UseBasicParsing "$CanonicalOrigin$path").StatusCode -eq 200) "health failed $path"};foreach($origin in @($CanonicalOrigin,'https://server.logisticmarket.ir','https://unknown.invalid')){$r=Invoke-WebRequest -UseBasicParsing "$CanonicalOrigin/api/health" -Headers @{Origin=$origin};if($origin -eq $CanonicalOrigin){Need ($r.Headers['Access-Control-Allow-Origin'] -eq $origin) 'canonical CORS failed'}else{Need ($r.Headers['Access-Control-Allow-Origin'] -ne $origin) 'unexpected CORS allow'}};Write-Output 'DEPLOYED_AND_VERIFIED'
